   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");

     const fields = [
       {
         input: document.getElementById("full-name"),
         error: document.getElementById("full-name-error"),
         validate: (value) => value.trim().length > 0
       },
       {
         input: document.getElementById("email"),
         error: document.getElementById("email-error"),
         validate: (value, input) => input.validity.valid && value.trim().length > 0
       },
       {
         input: document.getElementById("phone"),
         error: document.getElementById("phone-error"),
         validate: (value) => value.trim() === "" || /^\+?[0-9()\-\s]{7,}$/.test(value.trim())
       }
     ];

     const showError = ({ input, error }) => {
       input.setAttribute("aria-invalid", "true");
       input.setAttribute("aria-errormessage", error.id);
       error.hidden = false;
     };

     const clearError = ({ input, error }) => {
       input.removeAttribute("aria-invalid");
       input.removeAttribute("aria-errormessage");
       error.hidden = true;
     };

     const validateField = (field) => {
       const isValid = field.validate(field.input.value, field.input);

       if (isValid) {
         clearError(field);
       } else {
         showError(field);
       }

       return isValid;
     };

     fields.forEach((field) => {
       field.input.addEventListener("input", () => {
         if (!field.error.hidden) {
           validateField(field);
         }
       });

       field.input.addEventListener("blur", () => {
         if (!field.error.hidden) {
           validateField(field);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";
       statusMessage.className = "status-message";

       const invalidField = fields.find((field) => !validateField(field));

       if (invalidField) {
         statusMessage.textContent = "Please correct the highlighted fields and try again.";
         statusMessage.classList.add("error");
         invalidField.input.focus();
         return;
       }

       statusMessage.textContent = "Your support request is ready to send.";
       statusMessage.classList.add("success");
       form.reset();
       fields.forEach(clearError);
     });
