<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <main id="maincontent" tabindex="-1">
    <section class="support-card" aria-labelledby="support-heading">
      <p class="eyebrow">Support</p>
      <h1 id="support-heading">Contact our support team</h1>
      <p class="intro">Tell us how we can help and a support specialist will follow up as soon as possible.</p>

      <form id="support-form" novalidate>
        <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

        <div class="form-field">
          <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-required="true"
          >
          <p class="field-error" id="full-name-error" hidden>Error: Enter your full name.</p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
          <input
            id="email"
            name="email"
            type="email"
            inputmode="email"
            autocomplete="email"
            required
            aria-required="true"
          >
          <p class="field-error" id="email-error" hidden>Error: Enter a valid email address.</p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
          <input
            id="phone"
            name="phone"
            type="tel"
            inputmode="tel"
            autocomplete="tel"
            aria-describedby="phone-help"
          >
          <p class="field-help" id="phone-help">Expected format: +1 (555) 123-4567</p>
          <p class="field-error" id="phone-error" hidden>Error: Use a phone number like +1 (555) 123-4567.</p>
        </div>

        <button type="submit">Send message</button>
        <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const fields = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        describedBy: "",
        validate: (value) => value.trim().length > 0
      },
      {
        input: document.getElementById("email"),
        error: document.getElementById("email-error"),
        describedBy: "",
        validate: (value, input) => input.validity.valid && value.trim().length > 0
      },
      {
        input: document.getElementById("phone"),
        error: document.getElementById("phone-error"),
        describedBy: document.getElementById("phone").getAttribute("aria-describedby") || "",
        validate: (value) => value.trim() === "" || /^\+?[0-9()\-\s]{7,}$/.test(value.trim())
      }
    ];

    const showError = ({ input, error, describedBy }) => {
      const descriptionIds = [describedBy, error.id].filter(Boolean).join(" ");
      input.setAttribute("aria-invalid", "true");
      input.setAttribute("aria-errormessage", error.id);
      if (descriptionIds) {
        input.setAttribute("aria-describedby", descriptionIds);
      }
      error.hidden = false;
    };

    const clearError = ({ input, error, describedBy }) => {
      input.removeAttribute("aria-invalid");
      input.removeAttribute("aria-errormessage");
      if (describedBy) {
        input.setAttribute("aria-describedby", describedBy);
      } else {
        input.removeAttribute("aria-describedby");
      }
      error.hidden = true;
    };

    const validateField = (field) => {
      const isValid = field.validate(field.input.value, field.input);

      if (isValid) {
        clearError(field);
      } else {
        showError(field);
      }

      return isValid;
    };

    fields.forEach((field) => {
      field.input.addEventListener("input", () => {
        if (!field.error.hidden) {
          validateField(field);
        }
      });

      field.input.addEventListener("blur", () => {
        if (!field.error.hidden) {
          validateField(field);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";
      statusMessage.className = "status-message";

      const invalidField = fields.find((field) => !validateField(field));

      if (invalidField) {
        statusMessage.textContent = "Please correct the highlighted fields and try again.";
        statusMessage.classList.add("error");
        invalidField.input.focus();
        return;
      }

      statusMessage.textContent = "Your support request is ready to send.";
      statusMessage.classList.add("success");
      form.reset();
      fields.forEach(clearError);
    });
  </script>
</body>
</html>
